        imd.mint(who, collateral);
        vm.startPrank(who);
        imd.approve(address(vault), collateral);
        vault.lock(collateral);
        vault.draw(debt);
        vm.stopPrank();
    }

    function test_coverMustNotDropUnsyncedReceiptsFromTheRecord() public {
        _open(BORROWER, 180e18, 100e18);
        _open(KEEPER, 450e18, 250e18);

        // 100 imdUSD of revenue lands and is recorded.
        vm.prank(KEEPER);
        stable.transfer(address(treasury), 100e18);
        assertEq(treasury.sync(IERC20(address(stable))), 100e18);

        // A realized bad debt, the vault's way: crash, mark, liquidate to empty.
        primary.set(2.5e14);
        spot.set(2.5e14);
        vault.bark(BORROWER);
        vm.warp(vm.getBlockTimestamp() + 6 hours);
        usd.set(2000e8);
        vm.prank(KEEPER);
        vault.bite(BORROWER, 75e18); // 180 * 0.5 / 1.2: drains the position exactly
        (uint256 collateral,) = vault.positions(BORROWER);
