        // re-minted and the Treasury's balance simply falls by `bad`.
        vault.cover(BORROWER, bad);
        assertEq(stable.balanceOf(address(treasury)), arrived - bad);

        // Expected: everything that arrived is recorded. Actual: the burn moved the balance back
        // toward the old baseline of 100, so the next sync credits only (arrived - bad - 100): the
        // record under-reports by exactly `bad`, forever.
        treasury.sync(IERC20(address(stable)));
        assertEq(treasury.totalReceived(IERC20(address(stable))), arrived, "every receipt is recorded");
    }
}

