        treasury.withdraw(IERC20(address(stable)), APPROVED_OPERATOR, 1);

        // So the loss the Treasury is holding imdUSD for must be coverable. Top the Treasury up with the
        // fees that accrued during the demonstration above (they are burned and reminted, net zero).
        uint256 owed = vault.debtOf(BORROWER);
        vm.prank(KEEPER);
        stable.transfer(address(treasury), owed - bad);
        // On the committed code this reverts NoRealizedBadDebt because the position "still holds collateral".
        vault.cover(BORROWER, owed);
        assertEq(vault.totalBadDebt(), 0, "the realized loss is retired");
        assertEq(vault.debtOf(BORROWER), 0);
    }
}

