pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {MockIMD} from "src/MockIMD.sol";
import {ImdUSD} from "src/ImdUSD.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {Treasury} from "src/Treasury.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

contract ScratchFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private value;
    uint64 private updatedAt;

    constructor(uint256 v) {
        setValue(v);
    }

    function setValue(uint256 v) public {
        value = v;
        updatedAt = uint64(block.timestamp);
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, updatedAt);
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract ScratchMirror is ISwarmFeed {
    ISwarmFeed private immutable primary;

    constructor(ISwarmFeed p) {
        primary = p;
    }

    function latestValue() external view returns (uint256, uint64) {
        return primary.latestValue();
    }

    function isStale() external view returns (bool) {
        return primary.isStale();
    }

    function maxAge() external view returns (uint256) {
        return primary.maxAge();
    }
}

/// @dev Constants only: `vm.etch` copies code, not storage.
contract ScratchAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @notice `cover` burns the Treasury's imdUSD through ImdUSD.burn, which never passes through the
/// Treasury's receipt accounting (`sync` / `_withdraw`). The balance drops below `lastSynced`, and the
/// next `sync` clamps the baseline instead of crediting, so the next receipts up to the covered amount
/// never reach `totalReceived` — the same class of record loss the earlier `withdraw` fix closed.
contract CoverLostReceiptTest is Test {
    address private constant BORROWER = address(0xBA);
    address private constant KEEPER = address(0xBEEF);
    uint256 private constant ETH_USD = 2000 ether;

    MockIMD private collateral;
    ParameterizedVault private vault;
    ImdUSD private stable;
    Treasury private treasury;
    ScratchFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ScratchAggregator()).code);
        vm.warp(1_000_000);
        collateral = new MockIMD();
        primary = new ScratchFeed(uint256(1 ether) * 1e18 / ETH_USD); // $1 per IMD
        ScratchFeed health = new ScratchFeed(0.85 ether);
        ScratchMirror spot = new ScratchMirror(primary);
        vault = new ParameterizedVault(
            address(collateral), address(0), address(0), address(primary), address(health), address(spot)
        );
        stable = vault.stablecoin();
        treasury = vault.treasury();
    }

    function _open(address who, uint256 amount, uint256 debt) private {
        vm.prank(APPROVED_OPERATOR);
        collateral.mint(who, amount);
        vm.startPrank(who);
        collateral.approve(address(vault), amount);
        vault.lock(amount);
        vault.draw(debt);
        vm.stopPrank();
    }

    /// @dev Crash, mark, liquidate to empty: realized bad debt the vault's own way.
    function _drain() private returns (uint256 bad) {
        _open(BORROWER, 170 ether, 100 ether);
        _open(KEEPER, 450 ether, 250 ether);
        primary.setValue(uint256(0.5 ether) * 1e18 / ETH_USD);
        vault.bark(BORROWER);
        vm.warp(vm.getBlockTimestamp() + 6 hours);
        primary.setValue(uint256(0.5 ether) * 1e18 / ETH_USD);
        uint256 repayable = uint256(170 ether) * 0.5 ether / ((100 + vault.CHOP_PERCENT()) * 1e16);
        vm.prank(KEEPER);
        vault.bite(BORROWER, repayable);
        bad = vault.totalBadDebt();
        assertGt(bad, 0, "realized");
        primary.setValue(uint256(1 ether) * 1e18 / ETH_USD);
    }

    function test_aReceiptAfterCoverIsCounted() public {
        uint256 bad = _drain();
        IERC20 t = IERC20(address(stable));

        // 100 imdUSD of fees arrive (a transfer stands in for minted stability fees) and are synced,
        // together with the few wei of fees the liquidation itself minted here.
        vm.prank(KEEPER);
        stable.transfer(address(treasury), 100 ether);
        treasury.sync(t);
        uint256 recorded = treasury.totalReceived(t);
        assertEq(recorded, stable.balanceOf(address(treasury)), "fully synced");
        assertGe(recorded, bad, "fixture: the Treasury can cover the whole loss");

        // Anyone covers the realized bad debt from the Treasury's imdUSD. Balance falls below lastSynced.
        vault.cover(BORROWER, bad);
        assertEq(vault.totalBadDebt(), 0);
        assertLt(stable.balanceOf(address(treasury)), treasury.lastSynced(t), "burned past the baseline");

        // 50 more arrives and is synced. The record must grow by exactly that 50.
        vm.prank(KEEPER);
        stable.transfer(address(treasury), 50 ether);
        treasury.sync(t);
        assertEq(
            treasury.totalReceived(t), recorded + 50 ether, "everything that arrived must be in the running total"
        );
    }

    /// @dev What the smallest fix does: the vault calls the permissionless `sync` on its Treasury
    /// around the burn (credit arrivals before, lower the baseline after). Done here by hand, so it
    /// shows the record is right once `cover` does the same.
    function test_syncingAroundTheBurnKeepsTheRecordRight() public {
        uint256 bad = _drain();
        IERC20 t = IERC20(address(stable));
        vm.prank(KEEPER);
        stable.transfer(address(treasury), 100 ether);
        treasury.sync(t);
        uint256 recorded = treasury.totalReceived(t);

        treasury.sync(t); // before: credit anything unsynced
        vault.cover(BORROWER, bad);
        treasury.sync(t); // after: move the baseline down to the post-burn balance

        vm.prank(KEEPER);
        stable.transfer(address(treasury), 50 ether);
        treasury.sync(t);
        assertEq(treasury.totalReceived(t), recorded + 50 ether);
    }
}
